{
  "type": "object",
  "properties": {
    "code": {
      "type": "string"
    },
    "result": {
      "type": "object",
      "properties": {
        "content": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "integer",
                "description": "ID 编号",
                "title": "告警主键ID"
              },
              "alertBizId": {
                "type": "string",
                "title": "告警业务ID"
              },
              "alertCategory": {
                "type": "string",
                "title": "告警类别"
              },
              "alertLevel": {
                "type": "string",
                "title": "告警级别"
              },
              "createDate": {
                "type": "string",
                "title": "产生时间"
              },
              "status": {
                "type": "string",
                "title": "处理状态",
                "enum": [
                  "PENDING",
                  "PARTIAL_RECEIVED",
                  "FULLY_RECEIVED",
                  "PROCESSED",
                  "RESOLVED_CLOSED",
                  "CLOSED"
                ]
              },
              "sectorName": {
                "type": "string",
                "title": "扇区名称"
              },
              "sectorCode": {
                "type": "string",
                "title": "扇区编码"
              },
              "alertReason": {
                "type": "string",
                "title": "告警依据"
              },
              "responsibleSeatList": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "seatId": {
                      "type": "integer",
                      "title": "坐席ID"
                    },
                    "seatName": {
                      "type": "string",
                      "title": "坐席名称",
                      "description": "新增时不用传"
                    },
