                      "title": "坐席权限编号",
                      "description": "新增时不用传"
                    }
                  },
                  "required": [
                    "seatId",
                    "seatName",
                    "seatPermission"
                  ]
                },
                "title": "责任坐席"
              },
              "alertUavList": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
